    <div class="form-grid"><div class="field"><label for="staff-candidate">Existing customer</label><select id="staff-candidate" name="id" required><option value="">Select a registered customer</option><?php foreach ($sectionData['candidates'] as $candidate): ?><option value="<?= (int) $candidate['id'] ?>"><?= $this->escape($candidate['name']) ?> · <?= $this->escape($candidate['email']) ?></option><?php endforeach ?></select></div><div class="field"><label for="new-staff-role">Grant role</label><select id="new-staff-role" name="role"><option value="administrator">Administrator</option><option value="super_admin">Super administrator</option></select></div></div>
    <input type="hidden" name="status" value="active"><div class="admin-form-footer"><button class="button" type="submit" <?= !$sectionData['candidates'] ? 'disabled' : '' ?>>Grant staff access</button></div>
