  <section class="admin-panel admin-record-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Access control</span><h2>Current staff <span class="admin-count"><?= count($sectionData['records']) ?></span></h2></div></div>
    <?php if (!$sectionData['records']): ?><p class="admin-empty">No staff accounts were found.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Staff member</th><th>Role</th><th>Status</th><th>Access settings</th></tr></thead><tbody>
      <?php foreach ($sectionData['records'] as $record): $isSelf = (int) $record['id'] === (int) $admin['id']; ?><tr><td><strong><?= $this->escape($record['name']) ?><?= $isSelf ? ' (you)' : '' ?></strong><small class="table-subtext"><?= $this->escape($record['email']) ?></small></td><td><span class="status-badge status-role"><?= $this->escape(str_replace('_', ' ', $record['role'])) ?></span></td><td><span class="status-badge status-<?= $this->escape($record['status']) ?>"><?= $this->escape(ucfirst($record['status'])) ?></span></td><td><form class="staff-inline-form" method="post" action="<?= $this->escape(appUrl('/admin/staff/save')) ?>"><input type="hidden" name="csrf" value="<?= $this->escape($_SESSION['csrf'] ?? '') ?>"><input type="hidden" name="id" value="<?= (int) $record['id'] ?>"><label class="sr-only" for="staff-role-<?= (int) $record['id'] ?>">Role for <?= $this->escape($record['name']) ?></label><select id="staff-role-<?= (int) $record['id'] ?>" name="role"><option value="customer" <?= $record['role'] === 'customer' ? 'selected' : '' ?>>Customer</option><option value="administrator" <?= $record['role'] === 'administrator' ? 'selected' : '' ?>>Administrator</option><option value="super_admin" <?= $record['role'] === 'super_admin' ? 'selected' : '' ?>>Super administrator</option></select><select name="status" aria-label="Status for <?= $this->escape($record['name']) ?>"><option value="active" <?= $record['status'] === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $record['status'] !== 'active' ? 'selected' : '' ?>>Inactive</option></select><button class="button button-small" type="submit" <?= $isSelf ? 'disabled title="Use a different super administrator to change your own access."' : '' ?>>Save</button></form></td></tr><?php endforeach ?>
    </tbody></table></div><?php endif ?>
  </section>
</section>
